 async function exported(gid){await page.evaluate(()=>{document.querySelector('#carousel-export')?.remove();const f=document.createElement('iframe');f.id='carousel-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#carousel-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&document.querySelector('#carousel-export').contentDocument.querySelector('.nw-carousel-card'),{},gid);}
