  function span(n){return n.surface[1].x-n.surface[0].x;}await change('[data-motion-stream="sideScale"]','0.6');const small=(await pose(.225/5))[1];await change('[data-motion-stream="sideScale"]','1');assert.ok(span((await pose(.225/5))[1])>span(small));await change('[data-motion-stream="sideScale"]','0.82');const horizontal=await pose(.225/5);await change('[data-motion-stream="direction"]','vertical');assert.notDeepEqual(geometry(await pose(.225/5)),geometry(horizontal));await change('[data-motion-stream="cardRatio"]','frame');assert.equal(await page.$eval('[data-motion-stream="cardRatio"]',n=>n.value),'frame');await change('[data-motion-stream="cardRatio"]','1:1');await change('[data-motion-stream="direction"]','horizontal');
