  await pose(.225/5);const click=await page.$eval('.nw-motion-dialog iframe',(f,id)=>{const d=f.contentDocument,n=d.querySelector('[data-id="'+id+'"]'),fr=f.getBoundingClientRect(),r=n.offsetParent.getBoundingClientRect(),p=n.__nwMotionInstances[0].polygon.reduce((a,v)=>({x:a.x+v.x/4,y:a.y+v.y/4}),{x:0,y:0});return{x:fr.left+(r.left+p.x)*fr.width/f.clientWidth,y:fr.top+(r.top+p.y)*fr.height/f.clientHeight};},start[1].id);await page.mouse.click(click.x,click.y);await page.click('[data-motion-library-tab="elements"]');assert.equal(await page.$eval('[data-motion-layer="'+start[1].id+'"]',n=>n.getAttribute('aria-pressed')),'true');assert.equal(await page.$eval('.nw-motion-dialog iframe',(f,id)=>f.contentDocument.querySelector('[data-id="'+id+'"]').__nwTickerSelection.classList.contains('nw-motion-selected'),start[1].id),true);
